import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import gameService from '../services/gameService';
import MainLayout from '../components/layout/MainLayout';
import './GamePlayPage.css';

const WheelGame = ({ gameData }) => {
  const { game_name, game_content } = gameData;
  const items = game_content && JSON.parse(game_content).items ? JSON.parse(game_content).items : [];

  const textPos = { x: 0, y: 0 };
  const [rotationDeg, setRotationDeg] = useState(0);
  const [resultLabel, setResultLabel] = useState("Нажмите 'Крутить'");
  const spinningRef = useRef(false);
  const [isSpinning, setIsSpinning] = useState(false);
  const [keepTextUpright, setKeepTextUpright] = useState(true);

  const palette = [
    "#B3E5FC", // Light Blue
    "#81D4FA", // Cerulean
    "#4FC3F7", // Sky Blue
    "#29B6F6", // Deep Sky Blue
    "#03A9F4", // Blue
    "#039BE5", // Dark Blue
    "#0288D1", // Midnight Blue
    "#0277BD", // Prussian Blue
    "#01579B", // Navy Blue
    "#002171"  // Darker Navy
  ];

  useEffect(() => {
    if (items.length > 0) {
        // Устанавливаем цвета для элементов, если они еще не установлены
        // Если цвета уже есть в game_content, используем их
        const updatedItems = items.map((item, index) => ({
            ...item,
            color: item.color || palette[index % palette.length]
        }));
        // gameData.game_content будет обновлен где-то выше, здесь только отображение
    }
  }, [items]);

  const getPointerIndex = (deg, count) => {
    if (count <= 0) return -1;
    const adjusted = (((270 - deg) % 360) + 360) % 360;
    const step = 360 / count;
    const index = Math.floor(adjusted / step);
    return Math.min(Math.max(index, 0), count - 1);
  };

  const spin = () => {
    if (spinningRef.current || isSpinning || items.length === 0) return;
    spinningRef.current = true;
    setIsSpinning(true);
    setResultLabel("");

    const count = items.length;
    const current = rotationDeg;
    const targetIndex = Math.floor(Math.random() * count);
    const step = 360 / count;
    const targetCenterDeg = targetIndex * step + step / 2;
    const baseTargetRotation = 270 - targetCenterDeg;
    const extraTurns = Math.floor(Math.random() * (10 - 5 + 1)) + 5; // Случайные обороты
    const targetRotation = baseTargetRotation + 360 * extraTurns;

    const durationMs = 5000;
    const startTs = performance.now();
    const startRotation = current;
    const deltaToBase =
      (((baseTargetRotation - startRotation) % 360) + 360) % 360;
    const endRotation = startRotation + 360 * extraTurns + deltaToBase;

    const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

    const tick = (now) => {
      const elapsed = now - startTs;
      const t = Math.min(elapsed / durationMs, 1);
      const eased = easeOutCubic(t);
      const value = startRotation + (endRotation - startRotation) * eased;
      setRotationDeg(value);
      if (t < 1) {
        requestAnimationFrame(tick);
      } else {
        const finalIndex = getPointerIndex(value, count);
        const label = finalIndex >= 0 ? items[finalIndex]?.wordLabel ?? "" : "";
        setResultLabel(label);
        spinningRef.current = false;
        setIsSpinning(false);
      }
    };

    requestAnimationFrame(tick);
  };

  const WordWheel = ({ items, size, thickness, rotationDeg, keepTextUpright }) => {
    const computeAnglesEqual = (count) => {
      if (count <= 0) return [];
      const step = 360 / count;
      const spans = [];
      for (let i = 0; i < count; i++) {
        const startDeg = i * step;
        const endDeg = (i + 1) * step;
        spans.push({ startDeg, endDeg });
      }
      spans[spans.length - 1].endDeg = 360;
      return spans;
    };

    const donutSlicePath = (cx, cy, rOuter, rInner, startDeg, endDeg) => {
      const toRad = (d) => (d * Math.PI) / 180;
      const pt = (r, a) => ({
        x: cx + r * Math.cos(toRad(a)),
        y: cy + r * Math.sin(toRad(a)),
      });
      const largeArc = (endDeg - startDeg + 360) % 360 > 180 ? 1 : 0;
      const p1 = pt(rOuter, startDeg), p2 = pt(rOuter, endDeg);
      const p3 = pt(rInner, endDeg), p4 = pt(rInner, startDeg);
      return `M ${p1.x} ${p1.y} A ${rOuter} ${rOuter} 0 ${largeArc} 1 ${p2.x} ${p2.y} L ${p3.x} ${p3.y} A ${rInner} ${rInner} 0 ${largeArc} 0 ${p4.x} ${p4.y} Z`;
    };

    const wheelDraw = () => {
      const spans = computeAnglesEqual(items.length);
      const cx = size / 2;
      const cy = size / 2;
      const rOuter = Math.min(cx, cy) - 5;
      const rInner = Math.max(0, rOuter - thickness);
      const toRad = (d) => (d * Math.PI) / 180;
      const polarToCartesian = (r, angleDeg) => ({
        x: cx + r * Math.cos(toRad(angleDeg)),
        y: cy + r * Math.sin(toRad(angleDeg)),
      });

      return (
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
          <g transform={`rotate(${rotationDeg} ${cx} ${cy})`}>
            {spans.map((span, i) => {
              const d = donutSlicePath(
                cx,
                cy,
                rOuter,
                rInner,
                span.startDeg,
                span.endDeg
              );
              const midAngle = (span.startDeg + span.endDeg) / 2;
              const textRadius = (rOuter + rInner) / 2;
              const { x, y } = polarToCartesian(textRadius, midAngle);
              return (
                <g key={i}>
                  <path d={d} fill={items[i].color ?? "#ccc"} />
                  <text
                    x={x}
                    y={y}
                    fill="#222"
                    fontSize={Math.max(10, thickness * 0.3)}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    transform={
                      keepTextUpright
                        ? `rotate(${-rotationDeg} ${x} ${y})`
                        : undefined
                    }
                  >
                    {items[i].wordLabel}
                  </text>
                </g>
              );
            })}
          </g>
          <polygon points={`${cx - 6},10 ${cx + 6},10 ${cx},28`} fill="#333" />
        </svg>
      );
    };

    return wheelDraw();
  };

  return (
    <div className="wheel-play-area">
      <h1>{game_name}</h1>
      <div className="wheel-controls">
        <label className="checkbox-label">
          <input
            type="checkbox"
            checked={keepTextUpright}
            onChange={(e) => setKeepTextUpright(e.target.checked)}
          />
          Держать текст вертикально
        </label>
        <button
          onClick={spin}
          disabled={isSpinning || items.length === 0}
          className={`btn ${isSpinning ? 'btn-outline' : 'btn-primary'}`}
        >
          {isSpinning ? 'Крутим...' : 'Крутить колесо'}
        </button>
      </div>

      <div className="wheel-display">
        <WordWheel
          items={items}
          size={window.innerHeight > window.innerWidth ? window.innerWidth * 0.8 : window.innerHeight * 0.7}
          thickness={window.innerHeight > window.innerWidth ? window.innerWidth * 0.2 : window.innerHeight * 0.15}
          rotationDeg={rotationDeg}
          keepTextUpright={keepTextUpright}
        />
      </div>

      {resultLabel && (
        <div className="wheel-result alert alert-success">
          <strong>Победитель:</strong> {resultLabel}
        </div>
      )}
    </div>
  );
};


function GamePlayPage() {
  const { gameId } = useParams();
  const navigate = useNavigate();
  const [game, setGame] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchGame = async () => {
      try {
        setLoading(true);
        const response = await gameService.getGameById(gameId);
        setGame(response.game);
      } catch (err) {
        setError('Не удалось загрузить игру.');
        console.error('Ошибка загрузки игры:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchGame();
  }, [gameId]);

  if (loading) {
    return <MainLayout><div className="game-play-loading">Загрузка игры...</div></MainLayout>;
  }

  if (error) {
    return <MainLayout><div className="game-play-error">Ошибка: {error}</div></MainLayout>;
  }

  if (!game) {
    return <MainLayout><div className="game-play-error">Игра не найдена.</div></MainLayout>;
  }

  // В зависимости от game.game_type рендерим соответствующий компонент
  switch (game.game_type) {
    case 'wheel':
      return <WheelGame gameData={game} />;
    case 'match':
      return <MainLayout><div className="game-play-placeholder">Игра на совпадение скоро появится!</div></MainLayout>;
    case 'quiz':
      return <MainLayout><div className="game-play-placeholder">Викторина скоро появится!</div></MainLayout>;
    default:
      return <MainLayout><div className="game-play-error">Неизвестный тип игры.</div></MainLayout>;
  }
}

export default GamePlayPage;
